/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.searchCode();
        scwin.vJobMode = $c.frame.path("../").scwin.vJobMode;
        if (scwin.vJobMode === "M") {
            img_com_srch.hide();
            getParaIsurCd = $c.frame.path("../").fn_getParaIsurCd;
            scwin.vIsurCd = getParaIsurCd();
            getParaSeq = $c.frame.path("../").fn_getParaSeq;
            scwin.vSeq = getParaSeq();
            await scwin.getDelistMtbk();
        }
        if (scwin.vJobMode === "I") {
            await scwin.setFileDataHeader();
            await scwin.setSaveHeader();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20504.onpageload" });
    }
};

/**
 * @method
