///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "DELIB_COMITE_TP_CD",
        cnm: "cmb_DelibComiteTpCd"
    }, {
        cid: "DELIST_DELIB_CHRGTEAM_TP_CD",
        cnm: "cmb_ChrgDepCd"
    }];
    let objCod;
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='DELIB_COMITE_TP_CD','DELIST_DELIB_CHRGTEAM_TP_CD'";
    const sbmOptions = {
        id : "sbm_dts_Code",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Code=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Code.getRowCount(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
    //
    strCbd = "";
    strCbd = strCbd + ',Y' + "^" + '상장유지';
    strCbd = strCbd + ',D' + "^" + '상장폐지';
    cmb_ListComiteDelibRsltCd.CBData = strCbd;

    //
    /*strCbd = 'N' + "^" + '미대상';
    strCbd = strCbd + ',Y' + "^" + '대상';
    cmb_OpnReservYn.CBData = strCbd;
    cmb_OpnReservYn.Index = 0;*/

};

