};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (dts_fileList.getCellData(1, "fileInfo") === "") {
        dts_fileList.Reset();
    }
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("'회사코드(명)'을 입력하세요.");
        return;
    }
    if (med_ComiteDd.getValue() === "") {
        await $c.win.alert("'회의일'을 입력하세요.");
        return false;
    }
    if (cmb_DelibComiteTpCd.getValue() === "") {
        await $c.win.alert("'심의 위원회'를 입력하세요.");
        return;
    }
    let rtn = confirm('등록 하시겠습니까?');
    if (rtn === 1) {
        dts_ContentsInfo.setCellData(1, "REG_ID", js_emp_no);
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/DelistMtbk.do",
            ref : "dts_ContentsInfo,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

