    if (cmb_DelibComiteTpCd.getValue() === "") {
        await $c.win.alert("'심의 위원회'를 입력하세요.");
        return;
    }
    let rtn = confirm('수정 하시겠습니까?');
    if (rtn === 1) {
        dts_ContentsInfo.setCellData(1, "REG_ID", js_emp_no);
        const sbmOptions = {
